/**
 * Invoker's spells as the game defines them (`scripts/npc/heroes/npc_dota_hero_invoker.txt`
 * and `scripts/npc/items.txt` of Dota 2, version of 20 October 2026). The Rust
 * cooldown tracker reads the same data from `crates/racelink-contracts/data/dota-invoker.json`,
 * generated by `npm run gen:dota-data`.
 */

export type InvokerSpellDefinition = Readonly<{
  /** Internal name, as Game State Integration reports it. */
  name: string;
  /** English name, as the game shows it. */
  label: string;
  /** The orbs that invoke it. */
  orbs: string;
  cooldownSeconds: number;
  manaCost: number;
  /** Talents that change the cooldown, by their internal name: seconds added. */
  cooldownTalents: Readonly<Record<string, number>>;
}>;

export type InvokerData = Readonly<{
  /** The ten spells, grouped by orbs: Quas, then Wex, then Exort, then all three. */
  spells: readonly InvokerSpellDefinition[];
  /** Talent names in the order of `talent_1`…`talent_8` of Game State Integration. */
  talents: readonly string[];
  /** Items that shorten cooldowns: the fraction each takes off (they multiply). */
  cooldownReductionItems: Readonly<Record<string, number>>;
  /** Items whose use ends every cooldown. */
  refreshItems: readonly string[];
}>;

